"""Kaggriculture submission.

Production follows a recorded MMPQ trajectory ("the tape"), selected by the
first store to unlock. On top of that, every tape command that provably does
nothing in the current game is replaced with useful work the unit can perform
from the tile it already occupies.

Why that shape, from measurements on the official interpreter:

* The tape spends 43.2% of its unit-actions on movement and a further 12.2%
  (about 925 per game) on outright no-ops -- watering bare earth, caring for an
  animal that is not there -- because the recording came from a different game.
  With the 247 PASS commands per game, roughly 1,170 actions a game are idle.
* Substitutions must not move the unit. Allowing detours of even two tiles
  scored 0.88x the backbone, because moving desynchronises the tape's
  positional schedule and its route correction costs more than the work earns.
* Substitutions must not consume shared resources. Re-using the tape's seeds,
  animals, wheat or fertilizer turns its own scheduled commands into no-ops and
  scored 0.80x. The permitted actions therefore consume nothing.
* The tape's market head is load-bearing: it is an open-loop schedule whose
  purchases must land on time, and rewriting its selling logic left animals
  unplaced and 72 tiles empty. It is left untouched.
* CARE is the single most valuable free action. It banks a bonus paid on the
  animal's next yield, roughly doubling a goose's output and tripling a cow's,
  for one action and no resources.
"""
# --------------------------------------------------------------------------
# Recorded-trajectory backbone (verbatim, entry point renamed).
# --------------------------------------------------------------------------
import math
CROPS = ('WHEAT', 'CARROT', 'TOMATO', 'STRAWBERRY', 'MELON')
ANIMALS = ('GOOSE', 'COW', 'SHEEP')
PRODUCTS = CROPS + ('EGG', 'MILK', 'WOOL', 'FERTILIZER')
SEED_COST = dict(zip(CROPS, (10, 20, 50, 100, 80)))
FIRST = dict(zip(CROPS, (2, 2, 8, 10, 10)))
ANIMAL_COST = dict(zip(ANIMALS, (300, 400, 500)))
STRUCTURE = {'GOOSE': 'COOP', 'COW': 'PASTURE', 'SHEEP': 'PASTURE'}
ANIMAL_PRODUCT = {'GOOSE': 'EGG', 'COW': 'MILK', 'SHEEP': 'WOOL'}
PARAMS = {'WHEAT': (25, 400, 'sqrt', 0.8, 'log', 0.2), 'CARROT': (35, 450, 'hinge', 1.0, 'sqrt', 0.7), 'TOMATO': (60, 200, 'hinge', 0.4, 'sqrt', 0.6), 'STRAWBERRY': (120, 100, 'sqrt', 0.7, 'linear', 1.6), 'MELON': (250, 300, 'log', 0.2, 'sq', 3.6), 'EGG': (50, 332, 'hinge', 0.4, 'log', 0.2), 'MILK': (160, 122, 'sqrt', 0.6, 'linear', 1.6), 'WOOL': (200, 105, 'log', 0.2, 'sq', 3.2), 'FERTILIZER': (100, 200, 'linear', 0.4, 'linear', 0.4)}

def _shape(kind, x, scale):
    x = max(0.0, x)
    if kind == 'linear':
        return x
    if kind == 'sq':
        return x * x
    if kind == 'sqrt':
        return math.sqrt(x)
    if kind == 'log':
        return math.log1p(x)
    if kind == 'log10':
        return math.log10(1 + x)
    if kind == 'hinge':
        u = x / scale if scale > 0 else x
        return u + 8 * max(0.0, u - 1) ** 2 if scale > 0 else x
    return x

def price(item, inventory, market_params=None):
    """Exact official curve, including sparse optional parameter overrides."""
    base, scale, below, bt, above, at = PARAMS[item]
    patch = (market_params or {}).get(item, {})
    base, scale = (patch.get('base', base), patch.get('T', scale))
    origin = patch.get('I0', 10000)
    if inventory < origin:
        kind, frac = (patch.get('below_func', below), patch.get('below_target', bt))
        value = base + frac * base / _shape(kind, scale, scale) * _shape(kind, origin - inventory, scale)
    else:
        kind, frac = (patch.get('above_func', above), patch.get('above_target', at))
        value = base - frac * base / _shape(kind, scale, scale) * _shape(kind, inventory - origin, scale)
    return max(1, int(round(value)))

def _cmd(action):
    return action if isinstance(action, (list, tuple)) and action else ['PASS']

def _quantity(action, default=1):
    try:
        return max(0, int(action[2])) if len(action) > 2 else default
    except (TypeError, ValueError):
        return 0

def project(obs, planned_actions=None):
    """Project own unit actions before market, with sequential capacity checks.

    Harvest remains carried. Nightly automatic deposits occur after market and
    therefore are deliberately excluded from sellable stock on this turn.
    """
    farm = obs['farms'][obs['player']]
    private = obs['private']
    tiles = [[dict(t) if isinstance(t, dict) else t for t in row] for row in farm['tiles']]
    positions = [farm['farmer']] + list(farm.get('hands', []))
    bags = [dict(b) for b in private.get('inventories', [])]
    while len(bags) < len(positions):
        bags.append({})
    shed = dict(private.get('shed', {}))
    seeds = dict(private.get('seeds', {}))
    actions = planned_actions or {}
    acts = [_cmd(actions.get('farmer'))] + [_cmd(a) for a in actions.get('hands') or []]
    demand = {}
    for a in acts:
        if a[0] == 'PLANT' and len(a) > 1:
            demand[a[1]] = demand.get(a[1], 0) + 1
    blocked = {c for c, n in demand.items() if n > seeds.get(c, 0)}
    middle = len(tiles) // 2
    for uid, pos in enumerate(positions):
        if uid >= len(acts):
            break
        a, bag = (acts[uid], bags[uid])
        op = a[0]
        item = a[1] if len(a) > 1 else None
        count = _quantity(a)
        x, y = pos
        tile = tiles[y][x]
        at_shed = x in (middle - 1, middle) and y in (middle - 1, middle)
        if op == 'DROP' and at_shed:
            for key, n in list(bag.items()):
                shed[key] = shed.get(key, 0) + min(max(0, n), max(0, 100 - sum(shed.values())))
            bag.clear()
        elif op == 'PICKUP' and item and at_shed:
            n = min(count, shed.get(item, 0))
            shed[item] = shed.get(item, 0) - n
            bag[item] = bag.get(item, 0) + n
        elif op == 'PLACE' and item:
            valid_animal = item in ANIMALS and isinstance(tile, dict) and (tile.get('kind') == STRUCTURE[item]) and ('animal' not in tile)
            if valid_animal:
                if bag.get(item, 0):
                    bag[item] -= 1
                    tiles[y][x] = {'kind': STRUCTURE[item], 'animal': item, 'fed_today': False}
            elif at_shed:
                n = min(count, bag.get(item, 0), max(0, 100 - sum(shed.values())))
                shed[item] = shed.get(item, 0) + n
                bag[item] = bag.get(item, 0) - n
        elif tile == 'LOCKED':
            continue
        elif op == 'PLANT' and item in CROPS and (item not in blocked) and (tile is None) and (seeds.get(item, 0) > 0):
            seeds[item] -= 1
            tiles[y][x] = {'kind': 'PLANT', 'crop': item, 'planted_day': obs['day'], 'yield_units': 0 if item in ('TOMATO', 'STRAWBERRY') else 1, 'watered_today': False, 'fertilized_until_day': -1}
        elif op == 'BUILD_COOP' and tile is None:
            tiles[y][x] = {'kind': 'COOP'}
        elif op == 'BUILD_PASTURE' and tile is None:
            tiles[y][x] = {'kind': 'PASTURE'}
        elif op == 'DIG' and (not (isinstance(tile, dict) and 'animal' in tile)):
            tiles[y][x] = None
        elif isinstance(tile, dict):
            if op == 'WATER' and tile.get('kind') == 'PLANT' and (not tile.get('watered_today')):
                tile['watered_today'] = True
                crop = tile.get('crop')
                maximum = {'WHEAT': 4, 'CARROT': 3, 'MELON': 12}.get(crop)
                if maximum is not None and (maximum + 1) // 2 <= obs['day'] - tile['planted_day'] <= maximum:
                    bonus = 2 if tile.get('fertilized_until_day', -1) >= obs['day'] else 1
                    tile['yield_units'] = min({'WHEAT': 6, 'CARROT': 4, 'MELON': 6}[crop], tile.get('yield_units', 0) + bonus)
            elif op == 'HARVEST' and tile.get('yield_units', 0) > 0:
                crop = tile.get('crop')
                animal = tile.get('animal')
                mature = animal or (crop in CROPS and obs['day'] - tile.get('planted_day', obs['day']) >= FIRST[crop])
                if mature:
                    key = ANIMAL_PRODUCT[animal] if animal else crop
                    bag[key] = bag.get(key, 0) + tile['yield_units']
                    tile['yield_units'] = 0
                    if crop in ('WHEAT', 'CARROT', 'MELON'):
                        tiles[y][x] = None
            elif op == 'FEED' and 'animal' in tile and (not tile.get('fed_today')) and (bag.get('WHEAT', 0) > 0):
                bag['WHEAT'] -= 1
                tile['fed_today'] = True
            elif op == 'COLLECT_FERTILIZER' and 'animal' in tile and tile.get('fertilizer_available'):
                bag['FERTILIZER'] = bag.get('FERTILIZER', 0) + 1
                tile['fertilizer_available'] = False
            elif op == 'FERTILIZE' and tile.get('kind') == 'PLANT' and (bag.get('FERTILIZER', 0) > 0):
                bag['FERTILIZER'] -= 1
                tile['fertilized_until_day'] = max(tile.get('fertilized_until_day', -1), obs['day'] + 2)
    crops = {c: 0 for c in CROPS}
    animals = {a: 0 for a in ANIMALS}
    structures = {'COOP': 0, 'PASTURE': 0}
    empty = 0
    unfed = 0
    for row in tiles:
        for tile in row:
            if tile is None:
                empty += 1
            if not isinstance(tile, dict):
                continue
            if tile.get('crop') in crops:
                crops[tile['crop']] += 1
            if tile.get('animal') in animals:
                animals[tile['animal']] += 1
                unfed += not tile.get('fed_today')
            elif tile.get('kind') in structures:
                structures[tile['kind']] += 1
    carried = {p: sum((max(0, bag.get(p, 0)) for bag in bags)) for p in PRODUCTS + ANIMALS}
    return {'shed': shed, 'seeds': seeds, 'carried': carried, 'bags': bags, 'crops': crops, 'animals': animals, 'structures': structures, 'empty': empty, 'unfed': unfed, 'tiles': tiles}

def _fib(n):
    a, b = (1, 1)
    for _ in range(max(0, n)):
        a, b = (b, a + b)
    return a
