"""Runtime for a first-store-selected fixed MMPQ production tape."""
_MOVE={'NORTH':(0,-1),'SOUTH':(0,1),'WEST':(-1,0),'EAST':(1,0)}
_STATE={}
_TELEMETRY={'calls':0,'route_corrections':0,'weed_repairs':0,'missing_seeds':0,'market_skips':0}

def _step_toward(pos,target):
    if pos[0]<target[0]:return ['EAST']
    if pos[0]>target[0]:return ['WEST']
    if pos[1]<target[1]:return ['SOUTH']
    if pos[1]>target[1]:return ['NORTH']
    return ['PASS']

def _is_crop(tile):return isinstance(tile,dict) and tile.get('kind')=='PLANT'

def _market(obs,action,row,config):
    p=project(obs,action);farm=obs['farms'][obs['player']]
    cash=float(farm['money']);shed=dict(p['shed']);seeds=dict(p['seeds'])
    inventory=dict(obs['market']['inventory']);params=obs['market'].get('params')
    out=[];day=obs['day'];last=day==29
    keep={'WHEAT':0 if last else row[7][0],'FERTILIZER':0 if last else row[7][1]}
    sales=[]
    for item in PRODUCTS:
        n=max(0,shed.get(item,0)-keep.get(item,0))
        if n:sales.append((n*obs['market']['prices'].get(item,0),item,n))
    sales.sort(reverse=True)
    def sell_next():
        nonlocal cash
        if not sales or len(out)>=10:return False
        value,item,n=sales.pop(0)
        out.append(['SELL',item,n]);shed[item]-=n
        for _ in range(n):cash+=price(item,inventory[item],params);inventory[item]+=1
        return True
    def prefund(amount):
        while cash<amount and sell_next():pass
    def buy(op,item,quantity,cost):
        nonlocal cash
        if quantity<=0 or len(out)>=10:return 0
        prefund(quantity*(cost if cost is not None else price(item,inventory[item]-quantity,params)))
        if len(out)>=10:return 0
        capacity=max(0,100-sum(shed.values())) if op in ('BUY_ANIMAL','BUY_PRODUCT') else quantity
        count=0
        for _ in range(min(quantity,capacity)):
            unit_cost=cost if cost is not None else price(item,inventory[item]-1,params)
            if unit_cost>cash:break
            count+=1;cash-=unit_cost
            if op=='BUY_PRODUCT':inventory[item]-=1
            if op in ('BUY_PRODUCT','BUY_ANIMAL'):shed[item]=shed.get(item,0)+1
        if count:out.append([op,item,count])
        if count<quantity:_TELEMETRY['market_skips']+=1
        return count
    # Hires follow the reference daily production workforce and expire at night.
    wanted=max(0,int(row[6])-len(farm['hands']))
    for j in range(wanted):
        cost=_fib(farm['hires_today']+j)*int(config.get('farmHandCostMult',1))
        prefund(cost)
        if len(out)>=10 or cash<cost:break
        out.append(['HIRE']);cash-=cost
    # Unit actions have already happened. Purchases are for the next callback.
    for ci,crop in enumerate(CROPS):
        goal=int(row[3][ci]);gap=max(0,goal-seeds.get(crop,0))
        if gap:buy('BUY_SEED',crop,gap,SEED_COST[crop])
    for item,idx in [('WHEAT',0),('FERTILIZER',1)]:
        if not last:buy('BUY_PRODUCT',item,max(0,row[7][idx]-shed.get(item,0)),None)
    for ai,animal in enumerate(ANIMALS):
        count=p['animals'][animal]+p['carried'][animal]+shed.get(animal,0)
        buy('BUY_ANIMAL',animal,max(0,row[4][ai]-count),ANIMAL_COST[animal])
    land=len(farm['unlocked_quadrants'])
    for _ in range(max(0,row[5]-land)):
        cost=(1000,2000,4000)[land-1] if 1<=land<=3 else 10**12
        prefund(cost)
        if cash<cost or len(out)>=10:break
        out.append(['BUY_LAND']);cash-=cost;land+=1
    while sell_next():pass
    return out

def _tape_agent(obs,configuration=None):
    config=configuration or {};step=int(obs.get('step',24*obs['day']+obs['hour']))
    seat=int(obs.get('player',0));farm=obs['farms'][seat];st=_STATE.get(seat)
    if st is None or step==0 or step<=st['step']:
        st={'step':-1,'day':obs['day'],'repairs':{},'key':None};_STATE[seat]=st
    if obs['day']!=st['day']:st['repairs']={};st['day']=obs['day']
    st['step']=step
    shops=obs.get('town',{}).get('unlocked_shops',[])
    if step<72:row=_TAPES['opening'][min(step,71)]
    else:
        if st['key'] is None:st['key']=shops[0] if shops and shops[0] in _TAPES else 'BRUNCH_SPOT'
        row=_TAPES[st['key']][min(step,718)]
    positions=[farm['farmer']]+farm['hands'];bags=obs['private'].get('inventories',[])
    seeds=dict(obs['private'].get('seeds',{}));actions=[]
    for uid,pos in enumerate(positions):
        cmd=list(row[0][uid]) if uid<len(row[0]) and row[0][uid] else ['PASS']
        expected=row[1][uid] if uid<len(row[1]) else pos
        tile=farm['tiles'][pos[1]][pos[0]];bag=bags[uid] if uid<len(bags) else {}
        pending=st['repairs'].get(uid)
        if pending and list(pos)==pending['pos']:
            crop=pending['crop']
            if tile is None and seeds.get(crop,0)>0:
                cmd=['PLANT',crop];seeds[crop]-=1;pending['stage']='water'
            elif _is_crop(tile) and tile.get('crop')==crop and not tile.get('watered_today'):
                cmd=['WATER'];st['repairs'].pop(uid,None)
            else:st['repairs'].pop(uid,None);pending=None
        else:
            st['repairs'].pop(uid,None);pending=None
        if pending is None:
            # Rejoin a stored spatial route after an omitted hire or local repair.
            target=list(expected)
            if cmd[0] in _MOVE:
                dx,dy=_MOVE[cmd[0]];target=[min(9,max(0,target[0]+dx)),min(9,max(0,target[1]+dy))]
                if list(pos)!=list(expected):_TELEMETRY['route_corrections']+=1
                cmd=_step_toward(pos,target)
            elif list(pos)!=list(expected):
                cmd=_step_toward(pos,target);_TELEMETRY['route_corrections']+=1
            elif cmd[0]=='PLANT' and len(cmd)>1:
                crop=cmd[1]
                if isinstance(tile,dict) and tile.get('kind')=='WEED':
                    cmd=['DIG'];st['repairs'][uid]={'pos':list(pos),'crop':crop,'stage':'plant'}
                    _TELEMETRY['weed_repairs']+=1
                elif tile is None and seeds.get(crop,0)>0:seeds[crop]-=1
                else:
                    cmd=['PASS']
                    if tile is None:_TELEMETRY['missing_seeds']+=1
            elif cmd[0] in ('BUILD_PASTURE','BUILD_COOP') and isinstance(tile,dict) and tile.get('kind')=='WEED':
                cmd=['DIG'];_TELEMETRY['weed_repairs']+=1
            elif cmd[0]=='PASS' and isinstance(tile,dict) and tile.get('kind')=='WEED':
                cmd=['DIG'];_TELEMETRY['weed_repairs']+=1
            elif cmd[0]=='PASS' and _is_crop(tile) and not tile.get('watered_today') and tile.get('consecutive_unwatered',0)>0:
                cmd=['WATER']
        actions.append(cmd)
    action={'farmer':actions[0] if actions else ['PASS'],'hands':actions[1:],'market':[]}
    action['market']=_market(obs,action,row,config)
    _TELEMETRY['calls']+=1
    return action
_tape_agent.telemetry=_TELEMETRY

